r=Path(__file__).resolve().parent;out=r/'results';ctx=runpy.run_path(str(r/'compare_default_bridge.py'));Harness=ctx['Harness'];audit=json.loads((out/'bridge_audit.json').read_text());source=np.load(r.parent/'source_decoded.npz');origin=int(source['raw_stamp_ns'][0]);stamps=source['vendor_stamp_ns'];bridge_stamps=np.array(audit['source_odom_stamps_ns'],dtype='int64');missing=np.setdiff1d(stamps,bridge_stamps);t=(stamps-origin)/1e9;accepted=[e for e in audit['events'] if e['accepted']];rejected=[e for e in audit['events'] if e['rejected']];assert (audit['events'][0]['lio_source_stamp_ns']-origin)/1e9>3.6;assert (accepted[-1]['lio_source_stamp_ns']-origin)/1e9<210;assert not any(e['accepted'] and (e['lio_source_stamp_ns']-origin)/1e9>210 for e in audit['events']);assert (bridge_stamps[-1]-origin)/1e9>=216
